            uint8_t mtype;

            flash_memset(&qspi_cfg, 0, sizeof(qspi_configure_t));

            handle = &bf0_psram_handle[i].qspi_handle;

            qspi_cfg.Instance = (MPI_TypeDef *)bf0_psram_cfg[i].instance;
            mtype = bf0_psram_cfg[i].is_qspi;

            syslog(LOG_INFO, "bsp_psramc_init: [%lu] instance=%p "
                   "is_qspi=%d\n", (unsigned long)i,
                   qspi_cfg.Instance, mtype);

            if (qspi_cfg.Instance == hwp_qspi1)
                mtype = psram_get_default_type(1);
            else if (qspi_cfg.Instance == hwp_qspi2)
                mtype = psram_get_default_type(2);

            if (mtype != SPI_MODE_NOR)  // use auto detected type
                qspi_cfg.SpiMode = mtype;
            else    // use configure type
                qspi_cfg.SpiMode = bf0_psram_cfg[i].is_qspi;

            qspi_cfg.msize = bf0_psram_cfg[i].msize;
            qspi_cfg.base = bf0_psram_cfg[i].base_addr;
            if (PM_STANDBY_BOOT == SystemPowerOnModeGet())
                handle->wakeup = 1;
            else
                handle->wakeup = 0;

            syslog(LOG_INFO, "bsp_psramc_init: [%lu] SpiMode=%d "
                   "msize=0x%x base=0x%x clk_div=%d\n",
                   (unsigned long)i, qspi_cfg.SpiMode,
                   qspi_cfg.msize, qspi_cfg.base,
                   psram_clk_div[i]);

            res = HAL_MPI_PSRAM_Init(handle, &qspi_cfg,
                                     psram_clk_div[i]);
            g_psram_ready = (res == HAL_OK);

            syslog(LOG_INFO, "bsp_psramc_init: [%lu] "
                   "HAL_MPI_PSRAM_Init=%d g_psram_ready=%d\n",
                   (unsigned long)i, res, g_psram_ready);
        }
    }

    /* Verify PSRAM is actually accessible */
    if (g_psram_ready)
      {
        volatile uint32_t *psram_test =
            (volatile uint32_t *)0x60400000;
        *psram_test = 0xdeadbeef;
        if (*psram_test != 0xdeadbeef)
          {
            syslog(LOG_ERR, "bsp_psramc_init: PSRAM write "
                   "verify FAILED! read=0x%08lx\n",
                   (unsigned long)*psram_test);
            g_psram_ready = false;
            res = HAL_ERROR;
          }
        else
          {
            syslog(LOG_INFO, "bsp_psramc_init: PSRAM write "
                   "verify OK\n");
          }
      }

    syslog(LOG_INFO, "bsp_psramc_init: returning %d "
           "g_psram_ready=%d\n", res, g_psram_ready);
    return res;

