 */

if (g_psram_ready && qspi_cfg.Instance == hwp_qspi1)
  {
    volatile MPI_TypeDef *mpi =
        (volatile MPI_TypeDef *)hwp_qspi1;

    /* Set HWCCR: QPSRAM Quad Write command config.
     * IMODE=1(single), ADMODE=3(quad), ADSIZE=2(24bit),
     * ABMODE=0, ABSIZE=0, DCYC=0(no dummy), DMODE=3(quad)
     */

    mpi->HWCCR = (3 << MPI_HWCCR_DMODE_Pos)  /* DMODE=quad */
               | (0 << MPI_HWCCR_DCYC_Pos)    /* DCYC=0 */
               | (0 << MPI_HWCCR_ABSIZE_Pos)  /* ABSIZE=0 */
               | (0 << MPI_HWCCR_ABMODE_Pos)  /* ABMODE=0 */
               | (2 << MPI_HWCCR_ADSIZE_Pos)  /* ADSIZE=24bit */
               | (3 << MPI_HWCCR_ADMODE_Pos)  /* ADMODE=quad */
               | (1 << MPI_HWCCR_IMODE_Pos);  /* IMODE=single */

    /* Set CTRSAR/CTREAR: transparent address range for PSRAM.
     * PSRAM1 is at SBUS 0x60000000, 32MB.
     * Must be 1KB aligned (bits 0-9 ignored).
     */

    mpi->CTRSAR = 0x60000000;
    mpi->CTREAR = 0x62000000;

    /* Enable HWIFE (bit 20) for AHB access.
     * Without this, AHB reads/writes to the transparent range
     * are NOT intercepted by the MPI controller.
     */

    mpi->CR |= MPI_CR_HWIFE;
  }

