380	        /* Extra debug area at 0x20001F80 */
381	#define PSRAM_DBG2_BASE 0x20001F80
382	#define PSRAM_DBG2(n,v) ((volatile uint32_t *)PSRAM_DBG2_BASE)[(n)] = (v)
383	
384	        /* Dump chip PID (written by config_psram_pinmux at 0x20001F10,
385	         * but that overlaps with our DBG area — read the register directly)
386	         */
387	        uint32_t pid = (hwp_hpsys_cfg->IDR & HPSYS_CFG_IDR_PID_Msk)
388	                       >> HPSYS_CFG_IDR_PID_Pos;
389	        PSRAM_DBG2(0, pid);
390	        PSRAM_DBG2(1, hwp_hpsys_cfg->IDR);
391	
392	        /* Dump FLASH1 clock config register */
393	        volatile uint32_t *rcc = (volatile uint32_t *)0x40000000;
394	        PSRAM_DBG2(2, rcc[0x40/4]);  /* HCLKENR offset 0x40 */
395	        PSRAM_DBG2(3, rcc[0x44/4]);  /* FLASH_CFCR1 offset 0x44 */
396	
397	        /* Try raw manual PSRAM ID read (bypass HAL) */
398	        volatile MPI_TypeDef *mpi = (volatile MPI_TypeDef *)hwp_qspi1;
399	        uint32_t cr_save = mpi->CR;
400	        mpi->CR = 1;  /* EN only, no HWIFE */
401	        mpi->CCR1 = (1 << 0)    /* IMODE=single */
402	                  | (0 << 3)    /* ADMODE=none */
403	                  | (2 << 6)    /* ADSIZE=24bit */
404	                  | (0 << 8)    /* ABMODE=none */
405	                  | (0 << 11)   /* ABSIZE=0 */
406	                  | (0 << 13)   /* DCYC=0 */
407	                  | (1 << 18);  /* DMODE=single */
408	        mpi->DLR1 = 3 - 1;     /* 3 bytes */
409	        mpi->CMDR1 = 0x9f;     /* Read ID command */
410	        /* Wait for completion */
411	        for (volatile int d = 0; d < 1000; d++) {}
412	        uint32_t raw_id = mpi->DR;
413	        PSRAM_DBG2(4, raw_id);
414	        mpi->CR = cr_save;  /* restore CR */
415	
416	        /* Apply HWIFE fix */
417	        mpi->HWCCR = (3 << MPI_HWCCR_DMODE_Pos)
418	                   | (0 << MPI_HWCCR_DCYC_Pos)
419	                   | (0 << MPI_HWCCR_ABSIZE_Pos)
420	                   | (0 << MPI_HWCCR_ABMODE_Pos)
421	                   | (2 << MPI_HWCCR_ADSIZE_Pos)
422	                   | (3 << MPI_HWCCR_ADMODE_Pos)
423	                   | (1 << MPI_HWCCR_IMODE_Pos);
424	        mpi->CTRSAR = 0x60000000;
425	        mpi->CTREAR = 0x62000000;
426	        mpi->CR |= MPI_CR_HWIFE;
427	
428	        /* Dump MPI1 regs after fixup */
429	        PSRAM_DBG(5,  mpi1[0]);    /* CR      */
430	        PSRAM_DBG(6,  mpi1[16]);   /* HCMDR   */
431	        PSRAM_DBG(7,  mpi1[18]);   /* HRCCR   */
432	        PSRAM_DBG(8,  mpi1[20]);   /* HWCCR   */
433	        PSRAM_DBG(9,  mpi1[23]);   /* CTRSAR  */
434	        PSRAM_DBG(10, mpi1[24]);   /* CTREAR  */
435	
436	        /* Try SBUS read (no write — avoid crash) */
437	        volatile uint32_t *psram_sbus =
438	            (volatile uint32_t *)0x60000000;
439	        PSRAM_DBG2(5, psram_sbus[0]);  /* read first word */
440	        PSRAM_DBG2(6, psram_sbus[1]);  /* read second word */
441	
442	        /* Spin */
443	        PSRAM_DBG2(7, 0xBEEFCAFE);
444	        while (((volatile uint32_t *)PSRAM_DBG2_BASE)[8] != 0xCAFEBEEF)
445	          ;
446	      }
447	
448	    PSRAM_DBG(7, g_psram_ready);
449	    return res;

