1001	            w_lat = 7;
1002	
1003	
1004	        if (fix_lat)
1005	            r_lat = w_lat * 2; //10;
1006	        else
1007	            r_lat = w_lat; // = 6; //5;
1008	
1009	        /* configure AHB command */
1010	        HAL_FLASH_CFG_AHB_RCMD(handle, 7, r_lat - 1, 0, 0, 3, 7, 7);
1011	        HAL_FLASH_SET_AHB_RCMD(handle, HAL_OPSRAM_READ);
