1030	        HAL_FLASH_SET_X16_MODE(handle, 1);
1031	        //HAL_MPI_SET_REFRESH(handle, 1); // set to low refresh by default, 0.5 may cause more
1032	
1033	        sys_clk = HAL_QSPI_GET_CLK(handle);
1034	        sys_clk /= 2;
1035	        if (sys_clk <= 66 * 1000000)
1036	            w_lat = 3;
1037	        else if (sys_clk <= 109 * 1000000)
1038	            w_lat = 4;
1039	        else if (sys_clk <= 133 * 1000000)
1040	            w_lat = 5;
1041	        else if (sys_clk <= 166 * 1000000)
1042	            w_lat = 6;
1043	        else if (sys_clk <= 200 * 1000000)
1044	            w_lat = 7;
1045	
1046	        if (fix_lat)
1047	            r_lat = w_lat * 2; //10;
1048	        else
1049	            r_lat = w_lat; // = 6; //5;
1050	
1051	        //r_lat = 6;
1052	        //w_lat = 3;
