264	/**
265	* @brief  psram controller hardware initial.
266	* @retval 0 if success.
267	*/
268	int bsp_psramc_init(void)
269	{
270	    /* Check if bootloader already initialized PSRAM (nxboot handoff).
271	     * If the magic flag is set, PSRAM is live and must NOT be
272	     * re-initialized — doing so would destroy the image the bootloader
273	     * copied from NAND to PSRAM.
274	     */
275	
276	#define SF32LB58_HANDOFF_FLAG_ADDR  0x20001FF0
277	#define SF32LB58_HANDOFF_MAGIC      0x5053524d  /* "PSRM" */
278	
279	    if (*(volatile uint32_t *)SF32LB58_HANDOFF_FLAG_ADDR ==
280	        SF32LB58_HANDOFF_MAGIC)
281	      {
282	        /* Clear the flag so subsequent resets don't skip init */
283	
284	        *(volatile uint32_t *)SF32LB58_HANDOFF_FLAG_ADDR = 0;
285	        g_psram_ready = true;
286	        return 0;
287	      }
288	
289	    HAL_StatusTypeDef res = HAL_ERROR;
290	    uint32_t i;
291	    uint32_t psram_num;
292	    uint8_t idx;
293	    uint16_t psram_clk_div[] =
294	    {
295	#ifdef CONFIG_BSP_USING_PSRAM1
296	        1,
297	#endif /* CONFIG_BSP_USING_PSRAM1 */
298	#ifdef CONFIG_BSP_USING_PSRAM2
299	        1,
300	#endif /* CONFIG_BSP_USING_PSRAM2 */
301	    };
302	
303	    idx = 0;
304	
305	#ifdef CONFIG_BSP_USING_PSRAM1
306	    psram_clk_div[idx] = BSP_GetFlash1DIV();
307	    idx++;
308	#endif /* CONFIG_BSP_USING_PSRAM1 */
309	#ifdef CONFIG_BSP_USING_PSRAM2
310	    psram_clk_div[idx] = BSP_GetFlash2DIV();
311	    idx++;
312	#endif /* CONFIG_BSP_USING_PSRAM2 */
313	
314	    psram_num = sizeof(bf0_psram_cfg) / sizeof(bf0_psram_cfg[0]);
315	
316	#ifdef SOC_SF32LB56X
317	    /* extend MPI1 space to 64Mb for 56x if psram supported */
318	    hwp_hpsys_cfg->SYSCR |= HPSYS_CFG_SYSCR_REMAP;
319	#endif
320	
321	/* Debug area in SRAM — readable via JLink after crash.
322	 * Layout: [0]=psram_num  [1]=entry0_SpiMode  [2]=entry0_res
323	 *         [3]=entry1_SpiMode  [4]=entry1_res  [5]=final_res
324	 *         [6]=psram_verify  [7]=g_psram_ready
325	 */
326	#define PSRAM_DBG_BASE  0x20001F00
327	#define PSRAM_DBG(n,v)  ((volatile uint32_t *)PSRAM_DBG_BASE)[(n)] = (v)
328	
329	    PSRAM_DBG(0, psram_num);
330	
331	    /* Enable MPI1/MPI2 peripheral clocks — HAL_RCC_HCPU_ClockSelect
332	     * only sets the clock SOURCE (CSR), not the clock GATE (ENR2).
333	     * Without this, the SPI bus is inactive and PSRAM won't respond.
334	     */
335	
336	#ifdef CONFIG_BSP_USING_PSRAM1
337	    HAL_RCC_EnableModule(RCC_MOD_MPI1);
338	#endif
339	#ifdef CONFIG_BSP_USING_PSRAM2
340	    HAL_RCC_EnableModule(RCC_MOD_MPI2);
341	#endif
342	
343	    /* init as 0 in case reach here before bss is initialized */
344	    flash_memset(&bf0_psram_handle[0], 0, sizeof(bf0_psram_handle));
345	    g_psram_ready = false;
346	    for (i = 0; i < psram_num; i++)
347	    {
348	        if (bf0_psram_cfg[i].is_qspi)
349	        {
350	            FLASH_HandleTypeDef *handle;
351	            qspi_configure_t qspi_cfg;
352	            uint8_t mtype;
353	
354	            flash_memset(&qspi_cfg, 0, sizeof(qspi_configure_t));
355	
356	            handle = &bf0_psram_handle[i].qspi_handle;
357	
358	            qspi_cfg.Instance = (MPI_TypeDef *)bf0_psram_cfg[i].instance;
359	            mtype = bf0_psram_cfg[i].is_qspi;
360	
361	            if (qspi_cfg.Instance == hwp_qspi1)
362	                mtype = psram_get_default_type(1);
363	            else if (qspi_cfg.Instance == hwp_qspi2)
364	                mtype = psram_get_default_type(2);
365	
366	            if (mtype != SPI_MODE_NOR)  // use auto detected type
367	                qspi_cfg.SpiMode = mtype;
368	            else    // use configure type
369	                qspi_cfg.SpiMode = bf0_psram_cfg[i].is_qspi;
370	
371	            qspi_cfg.msize = bf0_psram_cfg[i].msize;
372	            qspi_cfg.base = bf0_psram_cfg[i].base_addr;
373	            if (PM_STANDBY_BOOT == SystemPowerOnModeGet())
374	                handle->wakeup = 1;
375	            else
376	                handle->wakeup = 0;
377	
378	            PSRAM_DBG(1 + i * 2, qspi_cfg.SpiMode);
379	
380	            res = HAL_MPI_PSRAM_Init(handle, &qspi_cfg,
381	                                     psram_clk_div[i]);
382	            if (res == HAL_OK)
383	                g_psram_ready = true;
384	
385	            PSRAM_DBG(2 + i * 2, res);
386	        }
387	    }
388	
389	    /* Debug: read MPI1 registers and test PSRAM */
390	    if (g_psram_ready && psram_num > 0)
391	      {
392	        /* Extra debug area at 0x20001F80 */
393	#define PSRAM_DBG2_BASE 0x20001F80
394	#define PSRAM_DBG2(n,v) ((volatile uint32_t *)PSRAM_DBG2_BASE)[(n)] = (v)
395	
396	        /* Dump chip PID */
397	        uint32_t pid = (hwp_hpsys_cfg->IDR & HPSYS_CFG_IDR_PID_Msk)
398	                       >> HPSYS_CFG_IDR_PID_Pos;
399	        PSRAM_DBG2(0, pid);
400	        PSRAM_DBG2(1, hwp_hpsys_cfg->IDR);
401	
402	        /* Dump correct RCC registers */
403	        volatile uint32_t *rcc = (volatile uint32_t *)0x40000000;
404	        PSRAM_DBG2(2, rcc[0x0C/4]);  /* ENR2: MPI1 gate = bit1 */
405	        PSRAM_DBG2(3, rcc[0x10/4]);  /* CSR: SEL_MPI1 = bits[5:4] */
406	
407	        FLASH_HandleTypeDef *handle0 = &bf0_psram_handle[0].qspi_handle;
408	        volatile MPI_TypeDef *mpi = (volatile MPI_TypeDef *)hwp_qspi1;
409	
410	        /* Dump MPI1 SR/CR before fix */
411	        PSRAM_DBG(5, mpi->SR);
412	        PSRAM_DBG(6, mpi->CR);
413	
414	        /* MPI1 might be stuck BUSY from HAL init. Disable/re-enable to clear. */
415	        mpi->CR &= ~1;  /* disable QSPI */
416	        for (volatile int d = 0; d < 100; d++) {}
417	        mpi->CR |= 1;   /* re-enable QSPI */
418	        for (volatile int d = 0; d < 100; d++) {}
419	
420	        /* Clear any pending status */
