462	/****************************************************************************
463	 * Public Functions
464	 ****************************************************************************/
465	
466	/****************************************************************************
467	 * Name: nxboot_get_state
468	 *
469	 * Description:
470	 *   Gets the current bootloader state and stores it in the nxboot_state
471	 *   structure passed as an argument. This function may be used to determine
472	 *   which slot is update slot and where should application save incoming
473	 *   firmware.
474	 *
475	 * Input parameters:
476	 *   state: The pointer to nxboot_state structure. The state is stored here.
477	 *
478	 * Returned Value:
479	 *   0 on success, -1 and sets errno on failure.
480	 *
481	 ****************************************************************************/
482	
483	int nxboot_get_state(struct nxboot_state *state)
484	{
485	  int primary;
486	  int secondary;
487	  int tertiary;
488	  int update;
489	  int recovery;
490	  struct nxboot_img_header primary_header;
491	  struct nxboot_img_header secondary_header;
492	  struct nxboot_img_header tertiary_header;
493	  struct nxboot_img_header *update_header;
494	
495	  memset(state, 0, sizeof *state);
496	
497	  syslog(LOG_INFO, "nxboot_get_state: opening %s\n",
498	         CONFIG_NXBOOT_PRIMARY_SLOT_PATH);
499	  primary = flash_partition_open(CONFIG_NXBOOT_PRIMARY_SLOT_PATH);
500	  syslog(LOG_INFO, "nxboot_get_state: primary fd=%d\n", primary);
501	  if (primary < 0)
502	    {
503	      return ERROR;
504	    }
505	
506	  secondary = flash_partition_open(CONFIG_NXBOOT_SECONDARY_SLOT_PATH);
507	  if (secondary < 0)
508	    {
509	      flash_partition_close(primary);
510	      return ERROR;
511	    }
512	
513	  tertiary = flash_partition_open(CONFIG_NXBOOT_TERTIARY_SLOT_PATH);
514	  if (tertiary < 0)
515	    {
516	      flash_partition_close(primary);
517	      flash_partition_close(secondary);
518	      return ERROR;
519	    }
520	
521	  get_image_header(primary, &primary_header);
522	  get_image_header(secondary, &secondary_header);
523	  get_image_header(tertiary, &tertiary_header);
524	
525	  update = secondary;
526	  recovery = tertiary;
527	  update_header = &secondary_header;
528	  state->update = NXBOOT_SECONDARY_SLOT_NUM;
529	  state->recovery = NXBOOT_TERTIARY_SLOT_NUM;
530	  if (get_image_flag(secondary, NXBOOT_CONFIRMED_PAGE_INDEX) &&
531	      validate_image(secondary))
532	    {
533	      /* Secondary image is confirmed and valid, use this as
534	       * a potential recovery.
535	       */
536	
537	      update = tertiary;
538	      recovery = secondary;
539	      state->recovery = NXBOOT_SECONDARY_SLOT_NUM;
540	      state->update = NXBOOT_TERTIARY_SLOT_NUM;
541	      update_header = &tertiary_header;
542	
543	      if (secondary_header.crc == primary_header.crc)
544	        {
545	          state->recovery_valid = true;
546	        }
547	    }
548	  else if (get_image_flag(tertiary, NXBOOT_CONFIRMED_PAGE_INDEX) &&
549	           tertiary_header.crc == primary_header.crc &&
550	           validate_image(tertiary))
551	    {
552	      state->recovery_valid = true;
553	    }
554	
555	  if (get_image_flag(primary, NXBOOT_CONFIRMED_PAGE_INDEX) ||
556	      primary_header.magic == NXBOOT_HEADER_MAGIC_INV)
557	    {
558	      state->primary_confirmed = true;
559	    }
560	
561	  state->next_boot = get_update_type(primary, update, recovery,
562	                                     &primary_header, update_header);
563	
564	  flash_partition_close(primary);
565	  flash_partition_close(secondary);
566	  flash_partition_close(tertiary);
567	  return OK;
568	}
