570	/****************************************************************************
571	 * Name: nxboot_get_confirm
572	 *
573	 * Description:
574	 *   This function can be used to determine whether primary image is
575	 *   confirmed or not. This provides more direct access to confirm
576	 *   state compared to nxboot_get_state function that returns the full
577	 *   state of the bootloader.
578	 *
579	 * Returned Value:
580	 *   1 means confirmed, 0 not confirmed, -1 and sets errno on failure.
581	 *
582	 ****************************************************************************/
583	
584	int nxboot_get_confirm(void)
585	{
586	  int primary;
587	  struct nxboot_img_header primary_header;
588	
589	  primary = flash_partition_open(CONFIG_NXBOOT_PRIMARY_SLOT_PATH);
590	  if (primary < 0)
591	    {
592	      return ERROR;
593	    }
594	
595	  get_image_header(primary, &primary_header);
596	  if (get_image_flag(primary, NXBOOT_CONFIRMED_PAGE_INDEX) ||
597	      primary_header.magic == NXBOOT_HEADER_MAGIC_INV)
598	    {
599	      return 1;
600	    }
601	
602	  return 0;
603	}
604	
605	/****************************************************************************
606	 * Name: nxboot_confirm
607	 *
608	 * Description:
609	 *   Confirms the image currently located in primary partition and marks
610	 *   its copy in update partition as a recovery.
611	 *
612	 * Returned Value:
613	 *   0 on success, -1 and sets errno on failure.
614	 *
615	 ****************************************************************************/
616	
617	int nxboot_confirm(void)
618	{
619	  int ret;
620	  int update;
621	  int primary;
622	  int secondary;
623	  int tertiary;
624	  int recovery;
625	  struct nxboot_state state;
626	
627	  nxboot_get_state(&state);
628	  if (state.primary_confirmed)
629	    {
630	      return OK;
631	    }
632	
633	  primary = flash_partition_open(CONFIG_NXBOOT_PRIMARY_SLOT_PATH);
634	  if (primary < 0)
635	    {
636	      return ERROR;
637	    }
638	
639	  secondary = flash_partition_open(CONFIG_NXBOOT_SECONDARY_SLOT_PATH);
640	  if (secondary < 0)
641	    {
642	      flash_partition_close(primary);
643	      return ERROR;
644	    }
645	
646	  tertiary = flash_partition_open(CONFIG_NXBOOT_TERTIARY_SLOT_PATH);
647	  if (tertiary < 0)
648	    {
649	      flash_partition_close(primary);
650	      flash_partition_close(secondary);
651	      return ERROR;
652	    }
653	
654	  if (state.update == NXBOOT_SECONDARY_SLOT_NUM)
655	    {
656	      update = secondary;
657	      recovery = tertiary;
658	    }
659	  else
660	    {
661	      update = tertiary;
662	      recovery = secondary;
663	    }
664	
665	  /* We need to mark both primary and update partitions as confirmed
666	   * (update partition will become recovery once confirmed) and
667	   * we have to remove confirmed flag from old recovery and set updated
668	   * flag there. This is to prevent old recovery still identify as
669	   * recovery and not to look as possible update. Therefore remove the
670	   * entire last sector (clears confirmed flag) and write updated
671	   * flag.
672	   */
673	
674	  ret = OK;
675	  if (set_image_flag(primary, NXBOOT_CONFIRMED_PAGE_INDEX) < 0)
676	    {
677	      ret = ERROR;
678	      goto confirm_done;
679	    }
680	
681	  if (set_image_flag(update, NXBOOT_CONFIRMED_PAGE_INDEX) < 0)
682	    {
683	      ret = ERROR;
684	      goto confirm_done;
685	    }
686	
687	  if (flash_partition_erase_last_sector(recovery) < 0)
688	    {
689	      ret = ERROR;
690	      goto confirm_done;
691	    }
692	
693	  if (set_image_flag(recovery, NXBOOT_UPDATED_PAGE_INDEX) < 0)
694	    {
695	      ret = ERROR;
696	      goto confirm_done;
697	    }
698	
699	confirm_done:
700	  flash_partition_close(primary);
701	  flash_partition_close(secondary);
702	  flash_partition_close(tertiary);
703	
704	  return ret;
705	}
706	
707	/****************************************************************************
708	 * Name: nxboot_perform_update
709	 *
710	 * Description:
711	 *   Checks for the possible firmware update and performs it by copying
712	 *   update image to primary slot or recovery image to primary slot in case
713	 *   of the revert. In any situation, this function ends with the valid
714	 *   image in primary slot.
715	 *
716	 *   This is an entry point function that should be called from the
717	 *   bootloader application.
718	 *
719	 * Input parameters:
720	 *   check_only: Only repairs corrupted update, but do not start another one
721	 *
722	 * Returned Value:
723	 *   0 on success, -1 and sets errno on failure.
724	 *
725	 ****************************************************************************/
726	
727	int nxboot_perform_update(bool check_only)
728	{
729	  int ret;
730	  struct nxboot_state state;
731	
732	  syslog(LOG_INFO, "nxboot_perform_update: start\n");
733	  ret = nxboot_get_state(&state);
734	  syslog(LOG_INFO, "nxboot_perform_update: get_state ret=%d\n", ret);
735	  if (ret < 0)
736	    {
737	      return ERROR;
738	    }
739	
740	  syslog(LOG_INFO, "nxboot_perform_update: next_boot=%d\n",
741	         state.next_boot);
742	  if (state.next_boot != NXBOOT_UPDATE_TYPE_NONE)
743	    {
744	      /* We either want to update or revert. */
745	
746	      syslog(LOG_INFO, "nxboot_perform_update: calling perform_update\n");
747	      ret = perform_update(&state, check_only);
748	      syslog(LOG_INFO, "nxboot_perform_update: perform_update ret=%d\n",
749	             ret);
750	      if (ret < 0)
751	        {
752	          syslog(LOG_ERR, "Update process failed. %s\n",
753	             strerror(errno));
754	        }
755	    }
756	
757	  return ret;
758	}
