52	    /* Discard build-id to ensure vectors start at flash base */
53	    /DISCARD/ : {
54	        *(.note.gnu.build-id)
55	    }
56	
57	    .vectors : {
58	        _stext = ABSOLUTE(.);
59	        /* Ensure vector table is properly aligned (must be at flash start) */
60	        . = ALIGN(512);
61	        KEEP(*(.vectors))
62	        /* workaround to avoid load address of .retm_data doesn't skip .vectors region */
63	        . = . + 4;
64	    } > rom
65	
66	    .retm_data : {
