#ifdef CONFIG_BOOT_NXBOOT
/****************************************************************************
 * Name: dump_nxboot_info
 *
 * Description:
 *   Read nxboot partition info and image headers, write to SRAM debug area
 *   at 0x20001D00 for JLink inspection.
 *
 *   Layout (each field is uint32_t):
 *     [0]  = 0x4E584254  ("NXBT" magic)
 *     [1]  = state.update
 *     [2]  = state.recovery
 *     [3]  = state.recovery_valid | (primary_confirmed << 1) | (next_boot << 2)
 *     [4]  = primary magic
 *     [5]  = primary image size
 *     [6]  = primary image CRC
 *     [7]  = primary version: (major << 32) | (minor << 16) | patch
 *     [8]  = secondary magic
 *     [9]  = secondary image size
 *     [10] = secondary image CRC
 *     [11] = secondary version
 *     [12] = tertiary magic
 *     [13] = tertiary image size
 *     [14] = tertiary image CRC
 *     [15] = tertiary version
 *     [16] = partition size (all same)
 *     [17] = errno if nxboot_get_state failed
 *     [18] = open result bitmask (bit0=primary, bit1=secondary, bit2=tertiary)
 ****************************************************************************/

static void dump_nxboot_info(void)
{
  volatile uint32_t *dbg = (volatile uint32_t *)0x20001D00;
  struct nxboot_state state;
  struct nxboot_img_header hdr;
  int ret;
  int fd;
  int i;
  static const char *const paths[3] =
  {
    CONFIG_NXBOOT_PRIMARY_SLOT_PATH,
    CONFIG_NXBOOT_SECONDARY_SLOT_PATH,
    CONFIG_NXBOOT_TERTIARY_SLOT_PATH
  };

  /* Clear debug area */
  for (i = 0; i < 20; i++)
    {
      dbg[i] = 0;
    }

  dbg[0] = 0x4E584254;  /* "NXBT" magic */

  /* Get nxboot state */
  ret = nxboot_get_state(&state);
  if (ret < 0)
    {
      dbg[17] = errno;
      return;
    }

  dbg[1] = (uint32_t)state.update;
  dbg[2] = (uint32_t)state.recovery;
  dbg[3] = (state.recovery_valid ? 1u : 0u) |
           (state.primary_confirmed ? 2u : 0u) |
           ((uint32_t)state.next_boot << 2);

  /* Read image headers from each partition */
  for (i = 0; i < 3; i++)
    {
      fd = open(paths[i], O_RDONLY);
      if (fd < 0)
        {
          dbg[18] |= (1u << i);
          continue;
        }

      if (read(fd, &hdr, sizeof(hdr)) == sizeof(hdr))
        {
          dbg[4 + i * 4] = hdr.magic;
          dbg[5 + i * 4] = hdr.size;
          dbg[6 + i * 4] = hdr.crc;
          dbg[7 + i * 4] = ((uint32_t)hdr.img_version.major << 16) |
                            (uint32_t)hdr.img_version.minor;
        }

      close(fd);
    }

  /* Store partition size (from primary) */
  dbg[16] = 0x00800000;  /* 8 MB per partition */
}
#endif

