/****************************************************************************
 * board/sf32lb58/sf32lb58-nxboot/scripts/ld.script
 *
 * Copyright (C) 2026 Yang Hongbo <yang.hongbo@iotpi.xyz>
 * SPDX-License-Identifier: Apache-2.0
 *
 * Linker script for SF32LB58 nxboot bootloader.
 * Bootloader runs from flash (XIP), uses SRAM for data/bss.
 * Copies app image from NAND to PSRAM at 0x60400000.
 ****************************************************************************/

/* SF32LB58 nxboot memory layout:
 *
 *   Flash (XIP):  QSPI5 NOR at 0x1C020000 (bootloader code)
 *   SRAM:         0x20000000 - 0x20180000 (1.5 MB)
 *   PSRAM:        0x60000000 - 0x62000000 (32 MB, for app image)
 */

MEMORY
{
  flash (rx)  : ORIGIN = 0x1C020000, LENGTH = 256K   /* XIP bootloader */
  sram (rwx)  : ORIGIN = 0x20000000, LENGTH = 1536K  /* RAM0-RAM5 */
}

OUTPUT_ARCH(arm)
EXTERN(_vectors)
__Vectors = _vectors;
ENTRY(_stext)

SECTIONS
{
    .vectors : {
        _stext = ABSOLUTE(.);
        . = ALIGN(512);
        KEEP(*(.vectors))
        . = . + 4;
    } > flash

    .text : {
        . = ALIGN(4);
        *(.text .text.*)
        *(.fixup)
        *(.gnu.warning)
        *(.rodata .rodata.*)
        *(.gnu.linkonce.t.*)
        *(.glue_7)
        *(.glue_7t)
        *(.got)
        *(.gcc_except_table)
        *(.gnu.linkonce.r.*)

        KEEP(*(.init))
        KEEP(*(.fini))

        . = ALIGN(4);
        _etext = ABSOLUTE(.);
    } > flash

    .ARM.extab : {
        *(.ARM.extab* .gnu.linkonce.armextab.*)
    } > flash

    __exidx_start = ABSOLUTE(.);
    .ARM.exidx : {
        *(.ARM.exidx* .gnu.linkonce.armexidx.*)
    } > flash
    __exidx_end = ABSOLUTE(.);

    .copy.table : {
        . = ALIGN(4);
        __copy_table_start__ = .;
        LONG (LOADADDR(.data))
        LONG (ADDR(.data))
        LONG (SIZEOF(.data) / 4)
        __copy_table_end__ = .;
    } > flash

    .zero.table : {
        . = ALIGN(4);
        __zero_table_start__ = .;
        LONG (__bss_start__)
        LONG ((__bss_end__ - __bss_start__) / 4)
        __zero_table_end__ = .;
    } > flash

    _eronly = ABSOLUTE(.);
    __etext = ALIGN(4);

    .data : {
        _sdata = ABSOLUTE(.);
        __data_start__ = .;
        *(vtable)
        *(.data)
        *(.data.*)
        *(.gnu.linkonce.d.*)

        . = ALIGN(4);
        __data_end__ = .;
        _edata = ABSOLUTE(.);
    } > sram AT > flash

    .bss : {
        . = ALIGN(4);
        _sbss = ABSOLUTE(.);
        __bss_start__ = .;
        *(.bss)
        *(.bss.*)
        *(.gnu.linkonce.b.*)
        *(COMMON)
        . = ALIGN(4);
        __bss_end__ = .;
        _ebss = ABSOLUTE(.);
    } > sram

    . = ALIGN(4);
    __end__ = .;
    PROVIDE(end = .);
    PROVIDE(_end = .);

    /* Stabs debugging sections. */
    .stab 0 : { *(.stab) }
    .stabstr 0 : { *(.stabstr) }
    .stab.excl 0 : { *(.stab.excl) }
    .stab.exclstr 0 : { *(.stab.exclstr) }
    .stab.index 0 : { *(.stab.index) }
    .stab.indexstr 0 : { *(.stab.indexstr) }
    .comment 0 : { *(.comment) }
    .debug_abbrev 0 : { *(.debug_abbrev) }
    .debug_info 0 : { *(.debug_info) }
    .debug_line 0 : { *(.debug_line) }
    .debug_pubnames 0 : { *(.debug_pubnames) }
    .debug_aranges 0 : { *(.debug_aranges) }
