129	/****************************************************************************
130	 * Name: cleanup_arm_nvic
131	 *
132	 * Description:
133	 *   Acknowledge and disable all interrupts in NVIC.
134	 *
135	 ****************************************************************************/
136	
137	static void cleanup_arm_nvic(void)
138	{
139	  int i;
140	
141	  UP_ISB();
142	  up_irq_disable();
143	
144	  for (i = 0; i < NR_IRQS; i += 32)
145	    {
146	      putreg32(0xffffffff, NVIC_IRQ_CLEAR(i));
147	    }
148	
149	  for (i = 0; i < NR_IRQS; i += 32)
150	    {
151	      putreg32(0xffffffff, NVIC_IRQ_CLRPEND(i));
152	    }
153	}
