157	 *
158	 * Description:
159	 *   Disable the SysTick system timer.
160	 *
161	 ****************************************************************************/
162	
163	static void systick_disable(void)
164	{
165	  putreg32(0, NVIC_SYSTICK_CTRL);
166	  putreg32(NVIC_SYSTICK_RELOAD_MASK, NVIC_SYSTICK_RELOAD);
167	  putreg32(0, NVIC_SYSTICK_CURRENT);
168	}
